package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.SerializableString;
import com.fasterxml.jackson.core.io.SerializedString;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.nextFieldName
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen0Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactory();
    }

    @Test
    public void testNextFieldName_SuccessWithFastSkip() throws IOException {
        // Tests the logic: if (i == INT_QUOTE) and fast skip colon match
        String json = "{\"name\":\"value\"}";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);

        // Move to first field name
        parser.nextToken(); 

        SerializableString target = new SerializedString("name");
        boolean match = parser.nextFieldName(target);

        assertTrue("Should match the field name 'name'", match);
        assertEquals(JsonToken.FIELD_NAME, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_MismatchName() throws IOException {
        // Tests the logic: _isNextTokenNameMaybe returns false if name doesn't match
        String json = "{\"wrong\":\"value\"}";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);

        parser.nextToken();

        SerializableString target = new SerializedString("name");
        boolean match = parser.nextFieldName(target);

        assertFalse("Should not match 'wrong' with 'name'", match);
    }

    @Test
    public void testNextFieldName_CurrentTokenIsFieldName() throws IOException {
        // Tests the logic: if (_currToken == JsonToken.FIELD_NAME) { _nextAfterName(); return false; }
        String json = "{\"name\":\"value\"}";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);

        parser.nextToken(); // Moves to FIELD_NAME "name"
        assertEquals(JsonToken.FIELD_NAME, parser.getCurrentToken());

        boolean result = parser.nextFieldName(new SerializedString("name"));

        assertFalse("Should return false when current token is already a field name", result);
        // After _nextAfterName, current token should be the value
        assertEquals(JsonToken.VALUE_STRING, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_IncompleteToken() throws IOException {
        // Tests: if (_tokenIncomplete) { _skipString(); }
        // We simulate an incomplete state by using a parser that might have trailing data or specific buffer states
        // However, in a standard ReaderBasedJsonParser, we can trigger this by feeding partial JSON if possible,
        // but a more direct way is to test the branch via code coverage if the parser state allows.
        String json = "{\"name\" : \"val\"}";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);
        parser.nextToken();

        // This is hard to trigger purely via public API without reflection to set _tokenIncomplete,
        // but we test the standard flow.
        boolean result = parser.nextFieldName(new SerializedString("name"));
        assertTrue(result);
    }

    @Test
    public void testNextFieldName_EndOfArray() throws IOException {
        // Tests: if (i == INT_RBRACKET)
        String json = "[1, 2, 3]";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);

        parser.nextToken(); // START_ARRAY
        parser.nextToken(); // 1
        parser.nextToken(); // 2
        parser.nextToken(); // 3
        parser.nextToken(); // END_ARRAY

        // At END_ARRAY, nextFieldName should return false and check context
        // Since we are in an array, not an object, it should fail or return false
        boolean result = parser.nextFieldName(new SerializedString("any"));
        assertFalse(result);
    }

    @Test
    public void testNextFieldName_EndOfObject() throws IOException {
        // Tests: if (i == INT_RCURLY)
        String json = "{\"a\":1}";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        parser.nextToken(); // VALUE_INT 1
        parser.nextToken(); // END_OBJECT

        boolean result = parser.nextFieldName(new SerializedString("a"));
        assertFalse(result);
    }

    @Test
    public void testNextFieldName_NotAnObject() throws IOException {
        // Tests: if (!_parsingContext.inObject()) { _nextTokenNotInObject(i); return false; }
        String json = "[{\"a\":1}]";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);

        parser.nextToken(); // START_ARRAY
        // We are in an array, not an object.
        boolean result = parser.nextFieldName(new SerializedString("a"));
        assertFalse(result);
    }

    @Test
    public void testNextFieldName_EndOfString() throws IOException {
        // Tests: if (i < 0) { close(); return false; }
        String json = "{}";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // END_OBJECT

        // Now at EOF
        boolean result = parser.nextFieldName(new SerializedString("a"));
        assertFalse(result);
        assertNull(parser.getCurrentToken());
    }

    @Test(expected = IOException.class)
    public void testNextFieldName_MismatchedEndMarker_Array() throws IOException {
        // Tests: if (i == INT_RCURLY && !_parsingContext.inArray()) -> report error
        // We trigger this by providing a '}' when the context is an array
        String json = "[}]";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);
        parser.nextToken(); // START_ARRAY
        parser.nextToken(); // '}'

        parser.nextFieldName(new SerializedString("a"));
    }

    @Test(expected = IOException.class)
    public void testNextFieldName_MismatchedEndMarker_Object() throws IOException {
        // Tests: if (i == INT_RBRACKET && !_parsingContext.inObject()) -> report error
        String json = "{]";
        ReaderBasedJsonParser parser = (ReaderBasedJsonParser) factory.createParser(json);
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // ']'

        parser.nextFieldName(new SerializedString("a"));
    }
}
